export function getArticlesForFranchise(teamCode: string): EditorialArticle[] {
  const code = (teamCode || "SRH").toUpperCase();
  const directMatches = EDITORIAL_ARTICLES.filter((a) => a.teamCode === code);
  if (directMatches.length > 0) {
    return directMatches;
  }
  return EDITORIAL_ARTICLES.filter((a) => a.teamCode === "SRH");
}

export function getEditorialArticleBySlug(slug: string): EditorialArticle | undefined {
  if (!slug) return undefined;

  let clean = decodeURIComponent(slug).trim().toLowerCase();
  clean = clean.replace(/^[/#]+|[/#]+$/g, "");
  if (clean.includes("/articles/")) {
    clean = clean.split("/articles/")[1];
  } else if (clean.startsWith("dugout/articles/")) {
    clean = clean.replace("dugout/articles/", "");
  } else if (clean.startsWith("articles/")) {
    clean = clean.replace("articles/", "");
  }
  clean = clean.replace(/^\/+|\/+$/g, "").trim();

  // 1. Direct slug match
  const directMatch = EDITORIAL_ARTICLES.find((a) => a.slug.toLowerCase() === clean);
  if (directMatch) return directMatch;

  // 2. Legacy mapped slug
  const mappedSlug = LEGACY_SLUG_MAP[clean] || LEGACY_SLUG_MAP[slug];
  if (mappedSlug) {
    const fromMap = EDITORIAL_ARTICLES.find((a) => a.slug.toLowerCase() === mappedSlug.toLowerCase());
    if (fromMap) return fromMap;
  }

  // 3. ID match (e.g. art-srh-01)
  const byId = EDITORIAL_ARTICLES.find((a) => a.id.toLowerCase() === clean);
  if (byId) return byId;

  // 4. Strip franchise prefix match
  const strippedClean = clean.replace(/^[a-z]{2,4}-/, "");
  const byStripped = EDITORIAL_ARTICLES.find((a) => {
    const aStripped = a.slug.toLowerCase().replace(/^[a-z]{2,4}-/, "");
    return aStripped === strippedClean || aStripped.includes(strippedClean) || strippedClean.includes(aStripped);
  });
  if (byStripped) return byStripped;

  // 5. Partial contains match
  const partial = EDITORIAL_ARTICLES.find((a) => a.slug.toLowerCase().includes(clean) || clean.includes(a.slug.toLowerCase()));
  if (partial) return partial;

  return undefined;
}
